/**
 * The 15 per-variant `AspectFieldInput` shapes plus the discriminated
 * union and its key-literal helper.
 *
 * Each variant extends `AspectFieldBaseInput` with its variant-specific
 * extras. Calculated fields are the structural odd one out — see
 * `AspectCalculatedFieldInput` below for the shape and the
 * `AspectFieldCalculation` types in `aspect.ts` for the read-side
 * projection (which lives as a slot on every existing variant's
 * typename rather than as its own typename).
 */
import type { AspectFieldBaseInput } from "./field-base.js";
import type { AspectFieldQrFormat, AspectNumericFieldFormat, AspectReferenceFieldFormat } from "./format.js";
import type { PicklistConfigInput, PicklistValueExInput } from "./picklist-config.js";
/** Mirror of `AspectAttachmentFieldInput`. Returns `ATTACHMENT_ID` on the wire. */
export interface AspectAttachmentFieldInput extends AspectFieldBaseInput {
    readonly mediaTypes?: readonly string[];
}
/** Mirror of `AspectBooleanFieldInput`. Returns `BOOLEAN` on the wire. */
export type AspectBooleanFieldInput = AspectFieldBaseInput;
/** Mirror of `AspectDateFieldInput`. Returns `DATE` on the wire. */
export type AspectDateFieldInput = AspectFieldBaseInput;
/** Mirror of `AspectDateTimeFieldInput`. Returns `DATETIME` on the wire. */
export type AspectDateTimeFieldInput = AspectFieldBaseInput;
/** Mirror of `AspectDecimalFieldInput`. */
export interface AspectDecimalFieldInput extends AspectFieldBaseInput {
    readonly format?: AspectNumericFieldFormat;
}
/** Mirror of `AspectGroupFieldInput`. Returns `GROUP_ID` on the wire. */
export type AspectGroupFieldInput = AspectFieldBaseInput;
/** Mirror of `AspectHandleFieldInput`. Returns `HANDLE` on the wire. */
export type AspectHandleFieldInput = AspectFieldBaseInput;
/** Mirror of `AspectHtmlFieldInput`. */
export type AspectHtmlFieldInput = AspectFieldBaseInput;
/** Mirror of `AspectJsonFieldInput`. */
export type AspectJsonFieldInput = AspectFieldBaseInput;
/** Mirror of `AspectNumberFieldInput` (long-typed). */
export interface AspectNumberFieldInput extends AspectFieldBaseInput {
    readonly format?: AspectNumericFieldFormat;
}
/**
 * Shared base for `AspectPicklistFieldInput` and
 * `AspectMultiPicklistFieldInput` (mirrors `AspectPicklistBaseFieldInput`).
 *
 * Legacy fields on the ultron record (`dynamicPicklistConfig`,
 * `parentFieldId`, `subFields`) are intentionally not surfaced — the
 * EDK's authoring contract for picklists goes through the newer
 * `config: PicklistConfigInput` and `picklistValues` / `values` slots.
 */
export interface AspectPicklistBaseFieldInput extends AspectFieldBaseInput {
    /** Legacy id-only list (used on update to reorder/persist). */
    readonly values?: readonly string[];
    readonly config?: PicklistConfigInput;
    readonly picklistValues?: readonly PicklistValueExInput[];
    readonly format?: AspectReferenceFieldFormat;
}
/** Mirror of `AspectPicklistFieldInput`. */
export type AspectPicklistFieldInput = AspectPicklistBaseFieldInput;
/** Mirror of `AspectMultiPicklistFieldInput`. */
export type AspectMultiPicklistFieldInput = AspectPicklistBaseFieldInput;
/** Mirror of `AspectTextFieldInput`. */
export interface AspectTextFieldInput extends AspectFieldBaseInput {
    readonly format?: AspectFieldQrFormat;
}
/** Mirror of `AspectUserFieldInput`. Returns `USER_ID` on the wire. */
export type AspectUserFieldInput = AspectFieldBaseInput;
/**
 * One parameter declaration on a calculated field. Mirrors
 * `AspectFieldCalculationParameterInput`. App-aspect calculated fields
 * generally don't use this slot — parameters are a workflow-context
 * feature ({{trigger}}, {{task}}, {{forEach}}) — but the input shape
 * surfaces it because it's shared with the workflow/task calculated-
 * column features. EDK v1 doesn't author parameters; leave unset.
 */
export interface AspectFieldCalculationParameterInput {
    readonly type: string;
    readonly paramValue?: unknown;
}
/**
 * One include-type rule for a calculated field. Mirrors
 * `AspectFieldCalculationIncludeTypeInput` discriminated input. Exactly
 * one of `auto` / `manual` / `picklist` should be set per entry.
 */
export interface AspectFieldCalculationIncludeTypeInput {
    readonly auto?: {
        readonly type?: string;
    };
    readonly manual?: {
        readonly type?: string;
    };
    readonly picklist?: {
        readonly picklistFieldId: string;
        readonly type?: string;
    };
}
/**
 * Inner calculation body — the raw expression text plus parameter
 * declarations and include-type rules. Mirrors
 * `AspectFieldCalculationInput`. `text` is the only required slot.
 */
export interface AspectFieldCalculationInput {
    readonly text: string;
    readonly parameters?: readonly AspectFieldCalculationParameterInput[];
    readonly includeTypes?: readonly AspectFieldCalculationIncludeTypeInput[];
}
/**
 * Mirror of `AspectCalculatedFieldInput` (`AspectCalculatedFieldCreateInput`
 * on the GraphQL graph; the update-side input relaxes `name` and
 * `calculation` to optional). The output field type
 * (NUMBER/DECIMAL/TEXT/...) is server-inferred from the expression
 * `text` — there is no explicit output-type slot.
 */
export interface AspectCalculatedFieldInput {
    readonly name: string;
    readonly columnName?: string;
    readonly description?: string;
    readonly tags?: readonly string[];
    readonly format?: AspectReferenceFieldFormat;
    readonly calculation: AspectFieldCalculationInput;
}
/**
 * Mirror of ultron's `AspectFieldInput` — exactly one of the 15 keys
 * is set per row in `AgentAspectInput.fields[]`. The serializer
 * enforces this; the type is `Partial<...>` so individual keys can be
 * absent without forcing all 14 others into the literal.
 */
export interface AspectFieldInput {
    readonly attachment?: AspectAttachmentFieldInput;
    readonly bool?: AspectBooleanFieldInput;
    readonly calculated?: AspectCalculatedFieldInput;
    readonly date?: AspectDateFieldInput;
    readonly dateTime?: AspectDateTimeFieldInput;
    readonly decimal?: AspectDecimalFieldInput;
    readonly group?: AspectGroupFieldInput;
    readonly handle?: AspectHandleFieldInput;
    readonly html?: AspectHtmlFieldInput;
    readonly json?: AspectJsonFieldInput;
    readonly number?: AspectNumberFieldInput;
    readonly picklist?: AspectPicklistFieldInput;
    readonly multiPicklist?: AspectMultiPicklistFieldInput;
    readonly text?: AspectTextFieldInput;
    readonly user?: AspectUserFieldInput;
}
/**
 * The 15-variant union as a literal-string union — used by the
 * serializer's lookup tables and tests.
 */
export type AspectFieldInputKey = "attachment" | "bool" | "calculated" | "date" | "dateTime" | "decimal" | "group" | "handle" | "html" | "json" | "number" | "picklist" | "multiPicklist" | "text" | "user";
